package com.networkmonitorpro.data.repository; import android.content.*; import androidx.lifecycle.*; import com.networkmonitorpro.data.db.AppDatabase; import com.networkmonitorpro.data.entity.DownloadHistory; import java.util.*; public class DownloadRepository{ private final AppDatabase db; public DownloadRepository(Context c){db=AppDatabase.get(c);} public LiveData<List<DownloadHistory>> all(){return db.downloadDao().all();} public void add(DownloadHistory d){AppExecutors.IO.execute(()->db.downloadDao().insert(d));} public void clear(){AppExecutors.IO.execute(()->db.downloadDao().clear());} }
